    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB1RC_0RC0LB_1RD1RA_1LD1LB
      with (l := [SWin 2; SCycL 2 0; SWin 1; SWinL 1]).
    vm_compute; reflexivity.
  - (* D1 *)
