    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB1RC_1RC1LD_1LA0RC_0LD1RC
      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_0RB1RC_1RC1LD_1LA0RC_0LD1RC
